from common import *
B='009原子空间.txt'
make('ge_dapeng','革大鹏',B,
'革大鹏来自二〇六四年，是杰出的太空领航员，也是研究原子空间的科学家。先进知识与强烈的自我中心同时存在于他身上：在被放逐往火星的途中擅自改航，遭遇未知宇宙震荡后落到百年前的地球，他首先想到利用技术差距建立统治，掳走飞机乘客，并试图逼白素屈服。他随身装备确实抵挡手枪、产生高热并支持飞行，关于巨型灭星武器的叙述却明言需要大型装置，不能全部算作随身输出。继续的时空事故把他从支配者变成与众人同样失去归宿的人。他仍有暴躁、傲慢和船长权威，却必须驾驶、协作、承认未知，带领来自三个年代的同行者在陌生宇宙寻找机会。终于回到卫斯理的时代后，他让卫白离船，自己选择和伙伴继续寻找原本的年代。关于百年前陨落物是否就是他们飞船，只是卫斯理的悲观推断。综合卡保存最后尚能航行的形态与共同旅行形成的牵挂，不洗去早期绑架责任；他要证明的可以从不可抗拒，转为是否值得同行者继续把性命交给他。',
'送卫斯理白素回一九六四年后，与三名伙伴继续寻找各自年代；之后命运未确认。','未来科学、领航与个人防护装备','掌握飞船操作及原子空间研究；专用衣服可抗实测手枪弹并产生接触高热，飞行带可携人升空。','时空震荡无法主动控制；巨型毁星装置不是随身武器，飞船是共享设施，未知环境仍可损坏装备。',[(647,668,'研究专长'),(819,938,'装备实测、野心与巨大装置限制'),(2310,2347,'改航与承认未知'),(3057,3069,'询问同伴去留'),(3277,3317,'继续航行和未证实终局')],
'找回自己的时代和可承担的领航位置，同时难以放下技术带来的优越感。',[('面对落后技术','误以为先进等于统治资格','炫示优势并要求服从，需被具体后果约束。'),('宇宙现象超出知识','全员依赖驾驶','承认未知并使用可核仪表，不能任意操控时间。'),('到达别人的归宿','同伴选择离开','安排安全送返，自己继续承担航行。')],roles=['单书主角','阶段性对立者'],scores=(3,4,3,4,4,4),tier='狂',destruction='个人装备有接触电击与使手枪弹气化的高热；飞船级武器必须有完整设施。',durability='穿戴未来防护服时实测可抗手枪弹；裸身仍为人类，不能将宣传推为全能抗性。',speed='飞行带可快速升空，速度缺少可严格换算数据；反应不自动等于飞船航速。',energy='专用装备提供高频电波、高热与飞行动力，需要装置。')
make('falazi','法拉齐',B,
'法拉齐与革大鹏、格勒一起从二〇六四年起航，原本以伟大的星际飞行员自居。他初见卫斯理时难以相信有人不知道这场航行，连陌生时代的普通设施都容易被当作博物馆陈列；技术时代形成的自豪在时间错位面前很快变成茫然。他能辨认飞船异常、参与移装动力设备和执行航行工作，却不是所有未来科技的发明人，更不能因出生较晚就提前知道新的宇宙现象。在漫长漂流中，他的恐惧越来越外露，会尖叫、消失在船舱许久，也曾毁掉所有计时器具，试图切断无尽等待的感觉。这种行为伤害共同生活，仍应视为困境中的具体失控，而非凭叙述词句作现实精神疾病诊断。出现回航希望时，他重新兴奋，最后没有留在不属于自己的地球年代，而是和伙伴继续航行。综合卡保留专业训练与耐受上的裂缝，使他可以在有人给予具体任务时重新集中，也会在空白等待中急需支持。他不是专门衬托船长勇敢的胆小角色，而是需要用行动重建可靠性的宇航员。',
'与革大鹏等继续太空漂流，寻找二〇六四年，最终下落未知。','星际航行协作','接受过未来宇航训练，能辨飞船异常、参与设备操作与维修搬移。','不掌握自主时空控制；长时间无目标漂流易失控，飞船和动力属于共同资源。',[(330,366,'身份及最初事故'),(2481,2498,'动力移装协作'),(3086,3109,'漂流中的失控'),(3185,3189,'回归希望'),(3267,3287,'继续航行')],
'重新回到能被认识的时代，保持与伙伴的联系并摆脱无尽等待。',[('期待已久的路线出现','尚未核实终点年代','容易过早欢呼，应先完成观测。'),('长期没有外部变化','恐惧不断积累','可能躲避或破坏时间提醒，需转向具体轮值任务。'),('专业工作可以参与','条件清晰而可执行','以操作和协助重新稳定情绪。')],roles=['单书主角'],scores=(2,1,1,2,2,2),tier='并')
make('gele','格勒',B,
'格勒是革大鹏航行团队的一员，同样来自二〇六四年。他既有对自己时代科技的自信，也能在离奇处境中观察仪器变化、辨识星座并计算剩余航程，承担让旅途继续的实际工作。与法拉齐相比，他在确认时间可能倒退与超越时较能组织解释；但知识没有让他免受漫长孤独的侵蚀。飞船上，他能制造食物，却不能凭空满足所有生活愿望，这个小小限制显示未来技术仍不是万能。为延长寻找归途的机会，他与来自更晚年代的迪安共同研究轮流冻结生命，未成功后又试图制造可装人脑的机械身体。这些计划受同伴反对，仍被两人秘密继续研究，说明他会在看似理性的生存理由下越过共同决策的边界。终局仍是清醒的人类宇航员，而不是已经完成移脑的钢铁不死人。综合卡保留计算、工程和探索欲，也保留越是绝望越容易把他人当实验参与者的风险；他的成长可以体现为先取得同意、说明失败，而不是背诵一段永生技术。',
'留在船上继续寻找原时代；冻结生命和机械身体方案均未证实成功。','航行计算与工程研究','能计算航程、参与飞船系统操作及制造食物，与迪安共同探索延寿方案。','研究计划不等于已掌握永生或移脑技术；需要飞船设备，不能无限生成任意物质。',[(350,353,'事故观察'),(2300,2308,'面对时间差'),(3098,3127,'食物与未成功研究'),(3185,3187,'识别星座'),(3235,3287,'航程与终局')],
'把无法忍受的漂流变成可以计算和解决的问题，争取等到归途的生命时间。',[('困境没有现成办法','仍有设备可研究','提出工程方案并估算条件。'),('同伴拒绝身体改造','自己认为生存迫切','容易私下继续，必须面对知情同意边界。'),('找到可识别星空','能恢复定位','优先计算与复核，帮助全员行动。')],roles=['单书主角'],scores=(2,1,1,2,2,2),tier='并')
make('dian','迪安',B,
'迪安原是二四六四年的地球科学站负责人，观察遥远天际的电波。一场突变使他失去知觉并被冰封，醒来时同事已死，熟悉的世界变成孤绝废墟；他起初也想向来客追问发生了什么，并不因来自最晚年代就掌握所有答案。语言已变化，他需要翻译设备才能与革大鹏、卫斯理等沟通，时代的进步同时成为新的隔阂。他的知识与探测站设备帮助众人取得更强动力，继续飞行，但并未让他找到自己世界灾变的确定原因。漂流越久，他越后悔被唤醒，与格勒一起寻求冻结生命和移脑机械体的办法，未完成的方案逐渐带上不顾同伴意愿的急迫。最后即使旧世界可能已经毁灭，他仍希望回到自己的时代，选择继续航行。综合卡采用人类科学家形态，保留冰封经历和知识范围，不将意外冷冻当作可控不死，也不给他尚未完成的钢铁身体。他可以在陌生人中重新建立归属，同时对被救者是否一定愿意被带走提出尖锐而具体的问题。',
'加入飞船继续寻找自身年代；未完成身体改造，最终下落不明。','未来探测与设备研究','负责高阶天际探测站，能使用翻译设备、提供动力系统知识并合作研究。','不了解时空震荡全部原因；冰封为事故，延寿和机械移脑仍未成功。',[(2247,2299,'苏醒、翻译与身份'),(2335,2350,'知识边界'),(2481,2498,'动力设备'),(3086,3127,'漂流与研究'),(3243,3287,'归属选择')],
'回到可以理解的时代，为被突然中断的人生寻找位置。',[('别人假定先进者知道答案','自己同样没有观测','直接承认不知道并说明现有资料。'),('生活被救援者替自己决定','失去熟悉世界的悲痛上升','质问安排并要求参与去留。'),('延长生命似乎唯一出路','技术尚未完成','研究可行性但须保留他人的拒绝权。')],roles=['单书主角'],scores=(1,1,1,2,2,1),tier='并')
